corrected_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;
use App\Models\ConsultationRoom;

// routes/channels.php
Broadcast::channel('telehealth.room.{roomId}', function (User $user, string $roomId) {
    $room = ConsultationRoom::where('room_uuid', $roomId)->first();
    if (!$room) {
        return false;
    }

    return $room->doctor_id === $user->id || $room->patient_id === $user->id;
});
